///
/// - `SelfVerify`: one VERIFY frame targeting `tx.sender` with scope `APPROVE_EXECUTION_AND_PAYMENT`.
/// - `DeploySelfVerify`: one DEFAULT frame (deploy) then one VERIFY frame as above.
/// - `OnlyVerifyPay`: one VERIFY frame (only_verify, scope `APPROVE_EXECUTION`) +
///   one VERIFY frame (pay, scope `APPROVE_PAYMENT`).
/// - `DeployOnlyVerifyPay`: DEFAULT deploy frame + OnlyVerifyPay pair.
///
/// Expiry-verifier frames (see `Frame::is_expiry_verifier`) are transparent; they
/// are skipped during shape matching but their indices are NOT included in
/// `frame_indices` (which holds only the semantically meaningful prefix frames).
///

// Shape: SelfVerify — VERIFY(exec+pay), no deploy.
if let Some((sv_pos, sv_pv, _)) = match_approving(0, APPROVE_EXECUTION_AND_PAYMENT) {
    return Ok(build(PrefixShape::SelfVerify, None, &[(sv_pos, sv_pv)]));
}
// Shape: DeploySelfVerify — DEFAULT + VERIFY(exec+pay).
if is_default(0)
    && let Some((sv_pos, sv_pv, _)) = match_approving(1, APPROVE_EXECUTION_AND_PAYMENT)
{
    return Ok(build(
        PrefixShape::DeploySelfVerify,
        Some(0),
        &[(sv_pos, sv_pv)],
    ));
}

// VERIFY frame (self_verify, only_verify, or pay).
if frame.mode != FrameMode::Verify as u8 {
    return Err(FrameValidationError::VerifyFrameNotVerifyMode {
        frame_index: idx,
    });
}

// EIP-8141 structural rule 3 restricts the target to
// tx.sender (None means sender) only for self_verify /
// only_verify frames. Rule 4 places no target requirement
// on the pay frame: it may target a non-sender sponsor,
// which approves payment via APPROVE(APPROVE_PAYMENT)
// when the frame executes.
let is_pay_frame = matches!(
    prefix.shape,
    PrefixShape::OnlyVerifyPay | PrefixShape::DeployOnlyVerifyPay
) && prefix.pay_index == Some(idx);
let target_ok = match frame.target {
    None => true,
    Some(addr) => addr == self.sender || is_pay_frame,
};
if !target_ok {
    return Err(FrameValidationError::VerifyTargetNotSender {
        frame_index: idx,
    });
}

// Scope restriction must match role.
let expected_scope = match prefix.shape {
    PrefixShape::SelfVerify | PrefixShape::DeploySelfVerify => {
        APPROVE_EXECUTION_AND_PAYMENT
    }
    PrefixShape::OnlyVerifyPay | PrefixShape::DeployOnlyVerifyPay => {
        // The only_verify frame comes before the pay frame.
        if prefix.pay_index == Some(idx) {
            APPROVE_PAYMENT
        } else {
            APPROVE_EXECUTION
        }
    }
};
if frame.scope_restriction() != expected_scope {
    return Err(FrameValidationError::WrongScopeRestriction {
        frame_index: idx,
        expected: expected_scope,
        actual: frame.scope_restriction(),

}

/// EIP-7623 token count over the frame and signature data, EIP-8250's nonce
/// calldata and EIP-8272's `rlp(recent_root_references)`, used for the
/// calldata floor. Frame transactions exist only from Hegota onward, which is
/// after Amsterdam, so EIP-7976's unweighted count (every byte costs
/// `STANDARD_TOKEN_COST`) always applies.
pub fn calldata_tokens(&self) -> u64 {
    self.data_fields()
        .fold(0u64, |acc, field| acc.saturating_add(field.len() as u64))
        .saturating_add(self.nonce_calldata().len() as u64)
        .saturating_add(self.recent_root_calldata().len() as u64)
        .saturating_mul(FRAME_TX_STANDARD_TOKEN_COST)
}

/// The EIP-7623 calldata floor: the least the frame and signature data may
/// cost, whatever execution actually consumes.
pub fn calldata_floor_gas(&self) -> u64 {
    self.calldata_tokens()
        .saturating_mul(FRAME_TX_TOTAL_COST_FLOOR_PER_TOKEN)
}

/// The mandatory costs, always charged in full: the intrinsic cost, the
/// per-frame cost, signature verification, and the value-transfer cost.
///
/// These are the terms `frame_tx_intrinsic_gas` and `calldata_floor_gas` share, which
/// is why they live in one function: the floor replaces only the data term, so a cost
/// that belongs on both sides of the `max_gas` comparison must be added here or it is
/// silently dropped whenever the floor binds.
pub fn mandatory_gas(&self) -> u64 {
    FRAME_TX_INTRINSIC_COST
        .saturating_add((self.frames.len() as u64).saturating_mul(FRAME_TX_PER_FRAME_COST))
        .saturating_add(self.signature_verification_cost())
        .saturating_add(self.value_transfer_cost())
}

/// EIP-8141 `value_transfer_cost`: `TX_VALUE_COST` per frame carrying value.
pub fn value_transfer_cost(&self) -> u64 {
    self.frames
        .iter()
        .filter(|frame| !frame.value.is_zero())
        .fold(0u64, |acc, _| acc.saturating_add(FRAME_TX_VALUE_COST))
}

/// EIP-8272 `recent_root_calldata`: `rlp(recent_root_references)`. The bytes
/// this EIP adds to the payload are priced exactly as EIP-8141 prices frame
/// and signature data, so they enter both `data_cost` and `calldata_tokens`.
/// Empty when no reference is declared, so a reference-free transaction's
/// gas is exactly the EIP-8141 figure.

/// The EIP-7825 cap is a *different* quantity — `frame_tx_intrinsic_gas +
/// total_frame_execution_gas`, state excluded — and is checked separately in
/// `validate_frame_tx_static`.
pub fn standard_gas_limit(&self) -> u64 {
    self.frame_tx_intrinsic_gas()
        .saturating_add(
            self.frames
                .iter()
                .map(|f| f.gas_limit)
                .fold(0u64, |acc, g| acc.saturating_add(g)),
        )
        .saturating_add(self.state_gas_limit())
}

/// Sum of the frames' EIP-8037 state budgets (`limits.state`). Kept separate
/// because state gas is excluded from the EIP-7825 transaction cap and is never
/// absorbed by the EIP-7623 calldata floor: both bound an execution-dimension
/// resource, so the floor branch of `max_gas` adds the state sum on top rather
/// than covering it. The state dimension is bounded by the encoding limit and by
/// the block's state-gas capacity instead.
pub fn state_gas_limit(&self) -> u64 {
    self.frames
        .iter()
        .map(|f| f.state_limit)
        .fold(0u64, |acc, g| acc.saturating_add(g))
}

/// EIP-8141 `calldata_floor_gas`: the mandatory costs plus the EIP-7623
/// floor over every byte this transaction carries. The mandatory costs are
/// always charged, so they sit on both sides of the `max_gas` comparison.
pub fn calldata_floor_total(&self) -> u64 {
    self.mandatory_gas()
        .saturating_add(self.recent_root_reference_intrinsic_gas())
        .saturating_add(self.calldata_floor_gas())
}

